"""SELF_REVIEW draft: unchanged old GLB payloads plus one scene floor. No product claim."""
import base64,copy,hashlib,json,math,struct,zlib
from pathlib import Path
ASSET='textile-separated-warping-and-treadle-loom-work-bay-scene-01'
TITLE='Separated Warping and Treadle-Loom Work Bay'
TOL=2e-7
OFFSETS={'warp': (-1.4, .35, .06), 'loom': (1.4, .35, .06)}
ROTATIONS={'warp': (1, 0), 'loom': (1, 0)}
def f32(x):return struct.unpack('<f',struct.pack('<f',x))[0]
def wrapper_matrix(key):
 # Exact determinant +1 signed permutation in glTF Y-up, column-major.
 # No quaternion, data baking, normal setter or simultaneous node TRS.
 c,s=ROTATIONS[key];x,y,z=OFFSETS[key]
 return [c,0,-s,0,0,1,0,0,s,0,c,0,f32(x),f32(z),f32(-y),1]
def unpack_glb(raw):
 magic,version,size=struct.unpack_from('<4sII',raw);assert magic==b'glTF' and version==2 and size==len(raw)
 n,kind=struct.unpack_from('<II',raw,12);assert kind==0x4e4f534a
 doc=json.loads(raw[20:20+n]);p=20+n;length,kind=struct.unpack_from('<II',raw,p);assert kind==0x004e4942
 blob=raw[p+8:p+8+length];assert len(blob)==length and len(doc['buffers'])==1
 assert doc['buffers'][0]['byteLength']<=len(blob)
 return doc,blob

def pack_glb(doc,blob):
 j=json.dumps(doc,separators=(',',':'),allow_nan=False).encode();j+=b' '*((-len(j))%4)
 b=bytes(blob)+b'\0'*((-len(blob))%4)
 return struct.pack('<4sII',b'glTF',2,12+8+len(j)+8+len(b))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(b),0x004e4942)+b

def compose(inputs):
 d=dict(asset={'version':'2.0','generator':'Source-preserving static scene composition'},scene=0,scenes=[{'name':TITLE,'nodes':[0]}],nodes=[{'name':'AssetRoot__'+ASSET,'children':[]}],meshes=[],materials=[],accessors=[],bufferViews=[],buffers=[])
 blob=bytearray();proof={}
 for key in ['warp', 'loom']:
  raw=inputs[key];src,b=unpack_glb(raw)
  assert not any(src.get(x) for x in ['textures','images','skins','animations','cameras','extensionsUsed','extensionsRequired'])
  assert not any(any(k in n for k in ['skin','camera']) for n in src['nodes'])
  start=len(blob);blob.extend(b);blob.extend(b'\0'*((-len(blob))%4))
  vi,ai,mi,ni,pi=(len(d[k]) for k in ['bufferViews','accessors','meshes','nodes','materials'])
  for old in src['bufferViews']:
   v=copy.deepcopy(old);assert v['buffer']==0;v['byteOffset']=v.get('byteOffset',0)+start;d['bufferViews'].append(v)
  for old in src['accessors']:
   a=copy.deepcopy(old);assert 'sparse' not in a;a['bufferView']+=vi;d['accessors'].append(a)
  d['materials'].extend(copy.deepcopy(src['materials']))
  for old in src['meshes']:
   m=copy.deepcopy(old)
   for p in m['primitives']:
    assert p.get('mode',4)==4 and not p.get('targets');p['indices']+=ai;p['material']+=pi
    p['attributes']={k:v+ai for k,v in p['attributes'].items()}
   d['meshes'].append(m)
  for old in src['nodes']:
   n=copy.deepcopy(old);n['name']=key+'__'+n.get('name','node')
   if 'mesh'in n:n['mesh']+=mi
   if 'children'in n:n['children']=[x+ni for x in n['children']]
   d['nodes'].append(n)
  wrapper=len(d['nodes']);d['nodes'].append({'name':'INSTANCE__'+key,'matrix':wrapper_matrix(key),'children':[x+ni for x in src['scenes'][src.get('scene',0)]['nodes']]});d['nodes'][0]['children'].append(wrapper)
  proof[key]={'source_glb_sha256':hashlib.sha256(raw).hexdigest(),'original_meshes':len(src['meshes']),'original_payload_bytes_unchanged':True,'original_internal_TRS_and_matrix_unchanged':True,'unit_scale':True,'rotation_degrees':0,'translation_zup_m':[f32(x)for x in OFFSETS[key]],'buffer_range':[start,start+len(b)]}
  assert bytes(blob[start:start+len(b)])==b
 floor,materials=make_floor();material_base=len(d['materials']);d['materials'].extend(materials)
 def array(values,component,kind):
  flat=[v for row in values for v in row] if kind=='VEC3' else values;fmt='f' if component==5126 else 'I'
  raw=struct.pack('<'+fmt*len(flat),*flat);offset=len(blob);blob.extend(raw);blob.extend(b'\0'*((-len(blob))%4));view=len(d['bufferViews']);d['bufferViews'].append({'buffer':0,'byteOffset':offset,'byteLength':len(raw)})
  a={'bufferView':view,'componentType':component,'count':len(values),'type':kind}
  if kind=='VEC3':a.update(min=[min(p[k]for p in values)for k in range(3)],max=[max(p[k]for p in values)for k in range(3)])
  index=len(d['accessors']);d['accessors'].append(a);return index
 primitives=[]
 for material in range(len(materials)):
  positions=[];normals=[]
  for tri,mat in floor:
   if mat!=material:continue
   a,b,c=tri;u=[b[k]-a[k]for k in range(3)];v=[c[k]-a[k]for k in range(3)];n=(u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]);length=math.sqrt(sum(x*x for x in n));assert length>0;n=[x/length for x in n]
   positions.extend((x,z,-y)for x,y,z in tri);normals.extend([(n[0],n[2],-n[1])]*3)
  primitives.append({'attributes':{'POSITION':array(positions,5126,'VEC3'),'NORMAL':array(normals,5126,'VEC3')},'indices':array(list(range(len(positions))),5125,'SCALAR'),'material':material_base+material,'mode':4})
 mesh=len(d['meshes']);d['meshes'].append({'name':'SceneOnlyContinuousWorkroomFloor','primitives':primitives});node=len(d['nodes']);d['nodes'].append({'name':'SCENE_ONLY__ContinuousWorkroomFloor','mesh':mesh,'extras':{'new_independent_model':False}});d['nodes'][0]['children'].append(node);d['buffers']=[{'byteLength':len(blob)}]
 assert len(d['meshes'])==86 and len(d['materials'])==9
 proof['floor_triangles']=len(floor);proof['triangles']=2136+len(floor);proof['single_scene_count']=1;proof['new_independent_model_count']=0
 return d,bytes(blob),proof

def make_floor():
 v=[(x,y,z)for x,y,z in [(-2.7,-1.8,0),(2.7,-1.8,0),(2.7,1.8,0),(-2.7,1.8,0),(-2.7,-1.8,.06),(2.7,-1.8,.06),(2.7,1.8,.06),(-2.7,1.8,.06)]]
 fs=[(0,3,2,1),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)];ts=[]
 for k,f in enumerate(fs):
  for i,j,l in [(f[0],f[1],f[2]),(f[0],f[2],f[3])]:ts.append(((v[i],v[j],v[l]),0 if k==1 else 1))
 mats=[{'name':n,'doubleSided':True,'pbrMetallicRoughness':{'baseColorFactor':rgba,'metallicFactor':0.,'roughnessFactor':.9}}for n,rgba in [('SceneOnlyWorkBayFloor',[.28,.29,.26,1]),('SceneOnlyWorkBayFloorEdge',[.15,.17,.16,1])]]
 return ts,mats

def main():
 import bpy,sys,time
 from mathutils import Vector
 OUT=Path(__file__).resolve().parent
 view=sys.argv[sys.argv.index('--tier-single-view')+1]if '--tier-single-view'in sys.argv else 'thumbnail';assert view in ['qa-front','thumbnail']
 inputs={k:zlib.decompress(base64.b64decode(v['compressed']))for k,v in INPUTS.items()}
 for k,raw in inputs.items():assert hashlib.sha256(raw).hexdigest()==INPUTS[k]['sha256']
 document,blob,proof=compose(inputs);model=pack_glb(document,blob);(OUT/'model.glb').write_bytes(model)
 bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)
 bpy.ops.import_scene.gltf(filepath=str(OUT/'model.glb'))
 parts=[o for o in bpy.context.scene.objects if o.type=='MESH'];assert len(parts)==86
 triangle_count=sum(len(p.vertices)-2 for o in parts for p in o.data.polygons);assert triangle_count==proof['triangles']
 points=[o.matrix_world@v.co for o in parts for v in o.data.vertices]
 lo=[min(v[k]for v in points)for k in range(3)];hi=[max(v[k]for v in points)for k in range(3)]
 assert abs(lo[2])<=TOL and abs(lo[0]+hi[0])<=TOL and abs(lo[1]+hi[1])<=TOL
 assert len({m for o in parts for m in o.data.materials})==9
 scene=bpy.context.scene;scene.render.engine='CYCLES';scene.cycles.samples=128;scene.cycles.use_adaptive_sampling=False;scene.cycles.use_denoising=False
 for layer in scene.view_layers:layer.cycles.use_denoising=False
 scene.use_nodes=False;scene.render.use_compositing=False;scene.render.threads_mode='FIXED';scene.render.threads=4
 scene.render.resolution_x=scene.render.resolution_y=640;scene.render.resolution_percentage=100
 scene.world=scene.world or bpy.data.worlds.new('Neutral static textile work bay');scene.world.use_nodes=True;scene.world.node_tree.nodes['Background'].inputs['Color'].default_value=(.3,.3,.3,1);scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value=.8
 scene.view_settings.view_transform='AgX';focus=Vector((0.,0.,.8))
 def aim(o,pos):o.location=pos;o.rotation_euler=(focus-o.location).to_track_quat('-Z','Y').to_euler()
 for name,pos,power,size in [('Key',(-8,-10,14),2200,9),('Fill',(10,-6,10),1500,8),('Rim',(4,12,12),1800,8)]:
  bpy.ops.object.light_add(type='AREA',location=pos);o=bpy.context.object;o.name='Preview_'+name;o.data.energy=power;o.data.shape='DISK';o.data.size=size;aim(o,pos)
 bpy.ops.object.camera_add();cam=bpy.context.object;cam.name='Preview_Camera';cam.data.type='ORTHO';scene.camera=cam;aim(cam,(-8,-13,9) if view=='qa-front' else (-8,-13,10));bpy.context.view_layer.update()
 rot=cam.rotation_euler.to_quaternion();right=rot@Vector((1,0,0));up=rot@Vector((0,1,0));xx=[v.dot(right)for v in points];yy=[v.dot(up)for v in points]
 cam.location+=right*((min(xx)+max(xx))/2-cam.location.dot(right))+up*((min(yy)+max(yy))/2-cam.location.dot(up));cam.data.ortho_scale=max(max(xx)-min(xx),max(yy)-min(yy))*1.12
 bpy.ops.mesh.primitive_plane_add(size=200,location=(0,0,-.0003));ground=bpy.context.object;ground.name='Preview_ground_not_asset';mat=bpy.data.materials.new('Preview_slate');mat.diffuse_color=(.20,.24,.25,1);ground.data.materials.append(mat)
 bpy.ops.wm.save_as_mainfile(filepath=str(OUT/'source.blend'),compress=True)
 qa={'review_mode':'SELF_REVIEW','status':'GEOMETRY_CREATED_NEEDS_MAKER_REVIEW','asset_id':ASSET,'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'glb_sha256':hashlib.sha256(model).hexdigest(),'mesh_count':86,'triangles':triangle_count,'materials':9,'bounds_min_m':lo,'bounds_max_m':hi,'composition':proof,'native_readback_claim':False,'normal_setter_or_vertex_bake_used':False,'render_configuration':{'samples':128,'threads':4,'engine':'CYCLES','denoising':False}}
 if '--geometry-only' not in sys.argv:
  view=sys.argv[sys.argv.index('--tier-single-view')+1]if '--tier-single-view'in sys.argv else 'thumbnail';assert view in ['qa-front','thumbnail']
  scene.cycles.samples=16 if view=='qa-front' else 128;scene.render.filepath=str(OUT/(view+'.png'));start=time.monotonic();bpy.ops.render.render(write_still=True);qa['render']={'view':view,'samples':scene.cycles.samples,'seconds':time.monotonic()-start,'original_pixels_reviewed':False}
 (OUT/'qa-report.json').write_text(json.dumps(qa,indent=2)+'\n')
 files={}
 for role,name in [('glb','model.glb'),('blend','source.blend'),('generator','generate.py'),('render','thumbnail.png')]:
  p=OUT/name
  if p.exists():files[role]={'path':f'assets/textile/{ASSET}/v1.0.0/{name}','size':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 if len(files)==4:
  meta={'id':ASSET,'version':'1.0.0','category':'scenes','assetKind':'scene','theme':'textile','style':'source-preserved-low-poly','title':TITLE,'description':'One static textile work bay from the original weaving-room scene program. One complete horizontal four-wing warping frame and one complete two-shaft treadle floor loom occupy two separate stations on a continuous scene-only floor. The front apron joins an open central aisle between the full unchanged machine footprints; the floor loom keeps its full warp paths, alternating fixed shed, reed, treadles and draped cloth, while the preparation frame keeps its full open winding cage and crank. Every original mesh, POSITION/NORMAL payload, internal hierarchy and constant PBR material is preserved byte for byte; only whole-instance translations and one floor are new. Unlike the older small flat weaving-frame and spool-bench corner or dye-vat preparation scene, this is a separate full-floor-loom and empty warping-frame work relation. One scene, zero new independent models. No yarn connects the machines. No animation, thread transfer, tension, operating weave, human fit, accessibility, structural load, manufacture or safety claim.','bounds':dict(zip(['x','y','z'],[hi[k]-lo[k]for k in range(3)]),unit='m'),'triangles':triangle_count,'materials':9,'files':files,'status':'review','license':'All rights reserved'}
  (OUT/'metadata.json').write_text(json.dumps(meta,indent=2)+'\n')
 print('SCENE_STAGE_COMPLETE',ASSET,triangle_count)

INPUTS={'warp': {'asset_id': 'textile-fixed-horizontal-four-wing-warping-frame-01', 'sha256': '57104fd1cf1f0b6085341127dfa520088476954598d50366277fe40220c02255', 'compressed': ''}, 'loom': {'asset_id': 'textile-fixed-two-shaft-treadle-floor-loom-01', 'sha256': 'c2b6396fb21b02b1aa085913bdc07e01c9cc3691116a690f907f2b771787fd51', 'compressed': ''}}
if __name__=='__main__':main()
